      "claim": "Alprazolam, a highly transferable analogue, has an absolute oral bioavailability of 80–100% in humans, strongly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Trazodone, a highly transferable analogue, has an absolute oral bioavailability of 63% in fasted volunteers, directly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C39"],
      "claim": "Eltrombopag, a highly transferable analogue, has an estimated oral bioavailability of at least 52% in healthy volunteers, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C41"],
      "claim": "Milvexian, a highly transferable analogue, showed approximately 100% oral bioavailability in a solution formulation relative to an IV microdose, strongly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Triazolam, a highly transferable analogue, has an absolute oral bioavailability of 30–40% in humans, still clearly above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C68"],
      "claim": "Brotizolam, a highly transferable analogue, has an absolute oral bioavailability of 70% in healthy volunteers, directly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Estazolam, a highly transferable analogue, has an oral bioavailability of 87% in healthy volunteers, strongly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C64"],
      "claim": "Selurampanel, a highly transferable analogue, has an estimated absolute oral bioavailability of approximately 60–70% in humans, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All highly transferable experimental analogues have measured oral bioavailability values well above the 20% threshold, ranging from about 30% to 100%, including multiple absolute human studies. The physicochemical prior is mixed and uncertain, but the consistent, direct experimental evidence from closely transferable molecules strongly supports a high oral bioavailability prediction.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement exists for the query molecule itself.",
    "The query's aqueous solubility and first-pass metabolism are not experimentally characterized; high lipophilicity may require formulation optimization.",
    "No exact structural match with human F data is available, though the transferable analogues cover relevant heteroaromatic and chlorophenyl features."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

